#include <mach/mach.h>
#include <vector>
#include <string>
#include <sstream>
#include <mach-o/dyld.h>
#include <substrate.h> // Requires CydiaSubstrate

// Simple AOB Scanner for iOS
uintptr_t AOBScan(const char* pattern) {
    uintptr_t baseAddr = _dyld_get_image_vmaddr_slide(0);
    // In a real scenario, you need to get the size of the Mach-O __TEXT segment
    // For simplicity, we assume scanning a large memory region
    uintptr_t scanSize = 0x5000000; 
    
    std::vector<int> patternBytes;
    std::stringstream ss(pattern);
    std::string byteStr;
    
    while (ss >> byteStr) {
        if (byteStr == "??" || byteStr == "?") {
            patternBytes.push_back(-1);
        } else {
            patternBytes.push_back(std::stoi(byteStr, nullptr, 16));
        }
    }
    
    uint8_t* scanBytes = (uint8_t*)baseAddr;
    for (uintptr_t i = 0; i < scanSize - patternBytes.size(); ++i) {
        bool found = true;
        for (size_t j = 0; j < patternBytes.size(); ++j) {
            if (patternBytes[j] != -1 && scanBytes[i + j] != patternBytes[j]) {
                found = false;
                break;
            }
        }
        if (found) {
            return (uintptr_t)&scanBytes[i];
        }
    }
    return 0;
}

// Function to write memory (Patching)
void PatchMemory(uintptr_t address, uint32_t patchInstruction) {
    if (address == 0) return;
    
    // Change memory protection to write
    mach_port_t task = mach_task_self();
    vm_protect(task, (vm_address_t)address, sizeof(patchInstruction), false, VM_PROT_READ | VM_PROT_WRITE | VM_PROT_COPY);
    
    // Write new instruction (Hex)
    *(uint32_t*)address = patchInstruction;
    
    // Restore memory protection
    vm_protect(task, (vm_address_t)address, sizeof(patchInstruction), false, VM_PROT_READ | VM_PROT_EXECUTE);
}

